        def height(node):
            if not node:
                return -1
            return 1 + max(height(node.left), height(node.right))
        h = height(root)
        m, n = h + 1, (1 << (h + 1)) - 1
        res = [[""] * n for _ in range(m)]
        def place(node, r, c):
            if not node:
                return
            res[r][c] = str(node.val)
            off = 1 << (h - r - 1)
            if off > 0:
                place(node.left, r + 1, c - off)
                place(node.right, r + 1, c + off)
        place(root, 0, (n - 1) // 2)
        return res

