class Solution {
    private int height(TreeNode node) {
        if (node == null) return -1;
        return 1 + Math.max(height(node.left), height(node.right));
    }
    private void place(TreeNode node, int r, int c, int h, String[][] res) {
        if (node == null) return;
        res[r][c] = String.valueOf(node.val);
        int off = 1 << (h - r - 1);
        if (off > 0) {
            place(node.left, r + 1, c - off, h, res);
            place(node.right, r + 1, c + off, h, res);
        }
    }
    public List<List<String>> printTree(TreeNode root) {
        int h = height(root);
        int m = h + 1, n = (1 << (h + 1)) - 1;
        String[][] grid = new String[m][n];
        for (String[] row : grid) Arrays.fill(row, "");
        place(root, 0, (n - 1) / 2, h, grid);
        List<List<String>> res = new ArrayList<>();
        for (String[] row : grid) res.add(Arrays.asList(row));
        return res;
    }
}

