from collections import deque

class Solution:
    def printTree(self, root):
        h = -1
        q = deque([root])
        while q:
            h += 1
            for _ in range(len(q)):
                node = q.popleft()
                if node.left: q.append(node.left)
                if node.right: q.append(node.right)
        m, n = h + 1, (1 << (h + 1)) - 1
        res = [[""] * n for _ in range(m)]
        q = deque([(root, 0, (n - 1) // 2)])
        while q:
            node, r, c = q.popleft()
            res[r][c] = str(node.val)
            off = 1 << (h - r - 1)
            if off > 0:
                if node.left: q.append((node.left, r + 1, c - off))
                if node.right: q.append((node.right, r + 1, c + off))
        return res

