    vector<vector<string>> printTree(TreeNode* root) {
        int h = -1;
        queue<TreeNode*> q;
        q.push(root);
        while (!q.empty()) {
            h++;
            int sz = q.size();
            while (sz--) {
                TreeNode* node = q.front(); q.pop();
                if (node->left) q.push(node->left);
                if (node->right) q.push(node->right);
            }
        }
        int m = h + 1, n = (1 << (h + 1)) - 1;
        vector<vector<string>> res(m, vector<string>(n, ""));
        queue<tuple<TreeNode*,int,int>> bfs;
        bfs.push({root, 0, (n - 1) / 2});
        while (!bfs.empty()) {
            auto [node, r, c] = bfs.front(); bfs.pop();
            res[r][c] = to_string(node->val);
            int off = 1 << (h - r - 1);
            if (off > 0) {
                if (node->left) bfs.push({node->left, r + 1, c - off});
                if (node->right) bfs.push({node->right, r + 1, c + off});
            }
        }
        return res;
    }
};

