class Solution {
    public List<List<String>> printTree(TreeNode root) {
        int h = -1;
        Queue<TreeNode> q = new LinkedList<>();
        q.offer(root);
        while (!q.isEmpty()) {
            h++;
            int sz = q.size();
            while (sz-- > 0) {
                TreeNode node = q.poll();
                if (node.left != null) q.offer(node.left);
                if (node.right != null) q.offer(node.right);
            }
        }
        int m = h + 1, n = (1 << (h + 1)) - 1;
        String[][] grid = new String[m][n];
        for (String[] row : grid) Arrays.fill(row, "");
        Queue<Object[]> bfs = new LinkedList<>();
        bfs.offer(new Object[]{root, 0, (n - 1) / 2});
        while (!bfs.isEmpty()) {
            Object[] cur = bfs.poll();
            TreeNode node = (TreeNode) cur[0];
            int r = (Integer) cur[1], c = (Integer) cur[2];
            grid[r][c] = String.valueOf(node.val);
            int off = 1 << (h - r - 1);
            if (off > 0) {
                if (node.left != null) bfs.offer(new Object[]{node.left, r + 1, c - off});
                if (node.right != null) bfs.offer(new Object[]{node.right, r + 1, c + off});
            }
        }
        List<List<String>> res = new ArrayList<>();
        for (String[] row : grid) res.add(Arrays.asList(row));
        return res;
    }
}

